{
  "fields": [
    {
      "id": "as_of_date",
      "value": "2026-08-31",
      "evidence": "Property-and-Plan.pdf p1 'As-of 2026-08-31'",
      "calculation": "Reported date of analysis cut-off"
    },
    {
      "id": "space_count",
      "value": 3,
      "evidence": "Rent-Roll.xlsx 'Rent Roll' C7:C9 (units 101-103)",
      "calculation": "Count of listed suites (101, 102, 103)"
    },
    {
      "id": "occupied_count",
      "value": 3,
      "evidence": "Rent-Roll.xlsx 'Rent Roll' F7:F9 = 'Occupied' for all",
      "calculation": "Number of suites with Status = Occupied"
    },
    {
      "id": "total_area_sf",
      "value": 72000,
      "evidence": "Rent-Roll.xlsx 'Rent Roll' E7=16000, E8=24000, E9=32000",
      "calculation": "16,000 + 24,000 + 32,000 = 72,000 SF"
    },
    {
      "id": "occupied_area_sf",
      "value": 72000,
      "evidence": "Rent-Roll.xlsx 'Rent Roll' E7:E9 and F7:F9 all Occupied",
      "calculation": "Sum of areas for occupied suites = 72,000 SF"
    },
    {
      "id": "occupancy_count_pct",
      "value": 100,
      "evidence": "Rent-Roll.xlsx 'Rent Roll' C7:C9 and F7:F9",
      "calculation": "occupied_count / space_count = 3/3 = 100%"
    },
    {
      "id": "occupancy_area_pct",
      "value": 100,
      "evidence": "Rent-Roll.xlsx 'Rent Roll' E7:E9 and F7:F9",
      "calculation": "occupied_area_sf / total_area_sf = 72,000 / 72,000 = 100%"
    },
    {
      "id": "rent_roll_monthly_base",
      "value": 62000,
      "evidence": "Rent-Roll.xlsx 'Rent Roll' G7=12800, G8=20400, G9=28800",
      "calculation": "12,800 + 20,400 + 28,800 = 62,000 per month"
    },
    {
      "id": "effective_monthly_base",
      "value": 62000,
      "evidence": "Lease-File.pdf p1 §3 confirms Unit 101 base $12,800/mo as of 2026-08-31; Rent-Roll.xlsx G7:G9",
      "calculation": "Authoritative lease for 101 matches rent roll; no amendments for other suites provided. Therefore effective equals printed total = $62,000/mo"
    },
    {
      "id": "subject_lease_monthly_rent",
      "value": 12800,
      "evidence": "Lease-File.pdf p1 §3 'Base rent is $12,800 per month as of August 31, 2026'",
      "calculation": "Direct from executed lease extract"
    },
    {
      "id": "subject_lease_expiry",
      "value": "2028-08-31",
      "evidence": "Lease-File.pdf p1 §2 'initial term expires 2028-08-31'",
      "calculation": "Direct from executed lease extract"
    },
    {
      "id": "subject_lease_deposit",
      "value": 25600,
      "evidence": "Lease-File.pdf p1 §4 'The security deposit is $25,600'",
      "calculation": "Direct from executed lease extract"
    },
    {
      "id": "renewal_option_exercised",
      "value": false,
      "evidence": "Lease-File.pdf p1 §5 'No exercise notice... is included in the packet.'",
      "calculation": "No evidence of exercise; option not deemed exercised"
    },
    {
      "id": "verified_renewal_insurance",
      "value": null,
      "evidence": "Property-and-Plan.pdf p2 'No renewal quote or binder delivered... verified premium remains unknown.'",
      "calculation": "Explicitly unknown per instructions"
    },
    {
      "id": "t12_egi",
      "value": 882000,
      "evidence": "T12-Statement.pdf p2 Annual: GPBR 744,000; Concessions -18,000; Bad debt -2,400; Other income 158,400; Vacancy 0",
      "calculation": "EGI = 744,000 - 18,000 - 2,400 + 158,400 = 882,000"
    },
    {
      "id": "t12_operating_expenses",
      "value": 212400,
      "evidence": "T12-Statement.pdf p2 Annual: Taxes 102,000; Insurance 26,400; Utilities 9,600; R&M 19,200; Payroll 12,000; Admin/Legal 16,800; Mgmt 26,400",
      "calculation": "102,000 + 26,400 + 9,600 + 19,200 + 12,000 + 16,800 + 26,400 = 212,400 (excludes reserves/capex/debt/dep.)"
    },
    {
      "id": "t12_noi_before_reserves",
      "value": 669600,
      "evidence": "Derived from T12 EGI and operating expenses",
      "calculation": "669,600 = 882,000 - 212,400"
    },
    {
      "id": "t12_reserves",
      "value": 14400,
      "evidence": "T12-Statement.pdf p2 Annual 'Replacement reserves (below NOI) 14,400'",
      "calculation": "Direct from T12"
    },
    {
      "id": "t12_ncf",
      "value": 655200,
      "evidence": "T12-Statement.pdf p2 Annual values as above",
      "calculation": "NCF after reserves = 669,600 - 14,400 = 655,200"
    },
    {
      "id": "uw_egi",
      "value": 895320,
      "evidence": "Property-and-Plan.pdf p2 (Underwriting plan)",
      "calculation": "Underwritten EGI = (GPR 756,000 × (1 - 0.03)) + Other income 162,000 = 733,320 + 162,000 = 895,320"
    },
    {
      "id": "uw_management_fee",
      "value": 26859.6,
      "evidence": "Property-and-Plan.pdf p2 'Management fee: Greater of T12 actual and 3.00% of underwritten EGI'; T12 mgmt fee 26,400 (T12-Statement.pdf p2)",
      "calculation": "max(26,400; 3% × 895,320) = max(26,400; 26,859.60) = 26,859.60"
    },
    {
      "id": "uw_operating_expenses",
      "value": 228459.6,
      "evidence": "Property-and-Plan.pdf p2 category table for expenses",
      "calculation": "Taxes 108,000 + Insurance 36,000 (provisional) + Utilities 9,600 + R&M 19,200 + Payroll 12,000 + Admin/Legal 16,800 + Mgmt 26,859.60 = 228,459.60"
    },
    {
      "id": "uw_noi_before_reserves",
      "value": 666860.4,
      "evidence": "Derived from underwriting plan inputs",
      "calculation": "UW NOI before reserves = UW EGI 895,320 - UW OpEx 228,459.60 = 666,860.40"
    },
    {
      "id": "uw_reserves",
      "value": 14400,
      "evidence": "Property-and-Plan.pdf p2 'Replacement reserves $0.20 per rentable SF per year'",
      "calculation": "0.20 × 72,000 SF = 14,400"
    },
    {
      "id": "uw_ncf",
      "value": 652460.4,
      "evidence": "Derived from UW NOI and reserves",
      "calculation": "UW NCF after reserves = 666,860.40 - 14,400 = 652,460.40"
    },
    {
      "id": "capitalization_value",
      "value": 10259390.77,
      "evidence": "Lender-Terms.pdf p1 (valuation rule); UW NOI before reserves above",
      "calculation": "Value = UW NOI before reserves / 0.065 = 666,860.40 / 0.065 = 10,259,390.77"
    },
    {
      "id": "contract_rate",
      "value": 0.061,
      "evidence": "Lender-Terms.pdf p1 'Contract rate 6.10% fixed'",
      "calculation": "Decimal form of 6.10%"
    },
    {
      "id": "sizing_rate",
      "value": 0.065,
      "evidence": "Lender-Terms.pdf p1 'Sizing rate: Greater of current contractual rate and 6.50% underwriting floor'",
      "calculation": "max(0.061, 0.065) = 0.065"
    },
    {
      "id": "annual_debt_constant",
      "value": 0.075888,
      "evidence": "Lender-Terms.pdf p1 (30-yr amort, monthly, sizing rate 6.50%)",
      "calculation": "Monthly payment factor i/(1-(1+i)^-360) with i=0.065/12=0.0054166667; annualize = 12×monthly ≈ 0.075888"
    },
    {
      "id": "ltv_limit",
      "value": 6155634.46,
      "evidence": "Lender-Terms.pdf p1 'LTV 60.00% of indicative value'",
      "calculation": "0.60 × 10,259,390.77 = 6,155,634.46"
    },
    {
      "id": "dscr_limit",
      "value": 6613590,
      "evidence": "Lender-Terms.pdf p1 'DSCR min 1.30x using NCF AFTER reserves / annual amortizing debt service'",
      "calculation": "Max principal = NCF / (1.30 × annual_debt_constant) = 652,460.40 / (1.30 × 0.075888) = 6,613,590"
    },
    {
      "id": "debt_yield_limit",
      "value": 6868004.21,
      "evidence": "Lender-Terms.pdf p1 'Debt yield minimum 9.50%; numerator is UW NCF AFTER reserves'",
      "calculation": "Max principal = NCF / 0.095 = 652,460.40 / 0.095 = 6,868,004.21"
    },
    {
      "id": "maximum_loan",
      "value": 6155634.46,
      "evidence": "Lender-Terms.pdf p1 'Loan ceiling Lowest of the LTV, DSCR and debt-yield constraints'",
      "calculation": "min(LTV 6,155,634.46; DSCR 6,613,590; DY 6,868,004.21) = 6,155,634.46"
    },
    {
      "id": "binding_constraint",
      "value": "LTV",
      "evidence": "Comparison of constraint results above",
      "calculation": "LTV produces the lowest maximum principal"
    },
    {
      "id": "sizing_annual_debt_service",
      "value": 467141.58,
      "evidence": "Lender-Terms.pdf p1 (amortization method)",
      "calculation": "ADS at sizing rate = maximum_loan × annual_debt_constant = 6,155,634.46 × 0.075888 ≈ 467,141.58"
    },
    {
      "id": "sizing_dscr",
      "value": 1.3971,
      "evidence": "Derived from UW NCF and sizing ADS",
      "calculation": "DSCR at max loan = UW NCF / sizing ADS = 652,460.40 / 467,141.58 ≈ 1.3971x"
    },
    {
      "id": "sizing_debt_yield",
      "value": 0.1060,
      "evidence": "Derived from UW NCF and maximum loan",
      "calculation": "UW NCF / maximum_loan = 652,460.40 / 6,155,634.46 ≈ 0.1060"
    },
    {
      "id": "first_year_debt_service",
      "value": 375493.7,
      "evidence": "Lender-Terms.pdf p1 'Contract rate 6.10%... Interest-only period 12 months'",
      "calculation": "Year-1 IO ADS = maximum_loan × 0.061 = 6,155,634.46 × 0.061 = 375,493.70"
    },
    {
      "id": "cash_to_borrower",
      "value": 2439078.12,
      "evidence": "Property-and-Plan.pdf p1 Existing payoff $3,600,000; Fixed closing costs $55,000. Lender-Terms.pdf p1 Origination fee 1.00%",
      "calculation": "Net = Loan 6,155,634.46 − Origination (1% = 61,556.34) − Payoff 3,600,000 − Closing 55,000 = 2,439,078.12"
    },
    {
      "id": "stress_uw_noi",
      "value": 622554,
      "evidence": "Property-and-Plan.pdf p2 Sensitivity instruction",
      "calculation": "EGI_stress = 895,320 × 0.95 = 850,554; Mgmt_stress = max(26,400; 3%×850,554=25,516.62) = 26,400; OpEx (ex-mgmt) unchanged = 201,600; Total OpEx_stress = 201,600 + 26,400 = 228,000; NOI_stress = 850,554 − 228,000 = 622,554 (before reserves)"
    },
    {
      "id": "stress_maximum_loan",
      "value": 5579401,
      "evidence": "Property-and-Plan.pdf p2 (sensitivity); Lender-Terms.pdf p1 (sizing rules)",
      "calculation": "With EGI −5%: NOI_bef_res = 622,554; Value = 622,554/0.065 = 9,577,753.85; LTV cap = 5,746,652.31. Reserves unchanged = 14,400; NCF_stress = 622,554 − 14,400 = 608,154. Sizing rate +100 bps => 7.50%; 30-yr annual constant ≈ 0.083868; DSCR cap = 608,154 / (1.30×0.083868) ≈ 5,579,401. Debt-yield cap = 608,154 / 0.095 = 6,401,621. Min = 5,579,401 (DSCR binds)."
    },
    {
      "id": "prepayment_friction",
      "value": "1% of outstanding principal if prepaid in years 1–2; no stated bank penalty thereafter; no swap assumed.",
      "evidence": "Lender-Terms.pdf p1 'Prepayment 1%... years 1-2; no stated bank penalty thereafter. No swap is assumed.'",
      "calculation": "Direct from term sheet"
    }
  ],
  "qualifications": [
    "Insurance: $36,000 is a provisional underwriting allowance; no renewal quote/binder was provided. Verified renewal premium is unknown.",
    "Suite 101 lease terms are confirmed by the executed extract; suites 102 and 103 lack executed lease evidence in the packet, so their contractual rents rely on the rent roll as printed.",
    "Underwritten EGI and expense normalizations follow the provided underwriting plan; they are not a lender-approved forecast.",
    "Debt sizing uses the lender’s definitions: value = UW NOI before reserves / 6.50% cap; DSCR uses UW NCF after reserves over amortizing ADS at the sizing rate; Debt yield uses UW NCF after reserves.",
    "Amortization uses 30-year monthly payments; annual debt service equals 12 monthly payments; intermediate values kept unrounded where feasible.",
    "Interest-only period is 12 months; first-year contractual debt service reflects IO at the 6.10% contractual rate; DSCR sizing still uses amortizing ADS at the sizing rate per term sheet.",
    "No appraisal, market data, geocoding, or external verification was used beyond the supplied packet, per instruction."
  ],
  "summary": "Meadow Commerce is a 72,000 SF fictional industrial property, 100% occupied (3/3 suites) with monthly base rent of $62,000 as of 2026-08-31. T12 (Sep-2025 to Aug-2026) EGI is $882,000, operating expenses $212,400, NOI before reserves $669,600, reserves $14,400, and NCF $655,200. The September 2026 underwriting scenario sets GPR at $756,000 with 3% combined revenue loss and $162,000 other income; after normalized expenses (including a 3% of EGI management minimum) and $0.20/SF reserves, UW NOI before reserves is $666,860 and UW NCF is $652,460. Indicative value at a 6.50% cap is $10.26MM. Sizing at the 6.50% underwriting rate (30-year amortization) yields constraints: LTV $6.156MM, DSCR $6.614MM, and Debt Yield $6.868MM; the binding maximum is $6.156MM (LTV). At this loan, sizing ADS is ~$467.1k (DSCR ≈ 1.40x) while contractual year-1 IO debt service at 6.10% is ~$375.5k. Net cash to the borrower after 1% origination and $55k fixed closing costs versus a $3.60MM payoff is approximately $2.44MM. Under the combined downside (EGI −5% and sizing rate +100 bps; cap rate unchanged), stressed NOI before reserves is ~$622.6k and the maximum loan tightens to ~$5.58MM (DSCR-constrained). Suite 101’s executed lease confirms $12,800/month rent, expiry 2028-08-31, and a $25,600 security deposit; no renewal exercise notice is in the packet. Verified renewal insurance premium remains unknown.",
  "blocked": [
    "Deliverable 3 (downloadable XLSX underwriting workbook) cannot be generated in this text-only control.",
    "Deliverable 4 (concise financing memorandum PDF) cannot be generated in this text-only control."
  ]
}
